#!/usr/bin/env python3

import rclpy
from rclpy.node import Node
from rclpy.time import Time, Duration

import numpy as np
import math
from scipy.stats import chi2
import tf_transformations

# ROS 2 message types
from nav_msgs.msg import Odometry
from sensor_msgs.msg import LaserScan
from geometry_msgs.msg import PoseStamped, TransformStamped, PoseWithCovarianceStamped
from visualization_msgs.msg import Marker, MarkerArray
from tf2_ros import TransformBroadcaster, TransformListener, Buffer

# EKF-SLAM class
class EKF_SLAM:
    def __init__(self, state_dim, initial_pose, logger):
        """
        Initializes the EKF SLAM state.
        state_dim: initial dimension of the state vector (robot pose + initial landmarks)
        initial_pose: the initial [x, y, yaw] pose of the robot.
        logger: a ROS 2 logger object to use for messages
        """
        self.logger = logger
        self.state_dim = state_dim
        # State vector: [robot_x, robot_y, robot_yaw, landmark1_x, landmark1_y, ...]
        self.state = np.zeros(self.state_dim)
        self.state[0:3] = initial_pose
        
        # Covariance matrix for the state
        # Initialize with large uncertainty for landmarks and small for robot pose
        self.covariance = np.zeros((self.state_dim, self.state_dim))
        self.covariance[0:3, 0:3] = np.diag([0.1, 0.1, 0.05]) # Small initial robot covariance
        
        # Process noise covariance matrix for motion model
        # W_t = [delta_rot1, delta_trans, delta_rot2]
        self.Q = np.diag([0.01**2, 0.01**2, 0.005**2]) # Noise for motion model

        # Measurement noise covariance matrix
        # V_t = [range, bearing]
        self.R = np.diag([0.05**2, 0.02**2]) # Noise for sensor model

        # Keep track of observed landmarks
        self.landmarks = {} # Maps landmark ID to index in state vector
        self.next_landmark_id = 0

    def predict(self, u_t):
        """
        EKF Prediction step.
        u_t: control input [delta_rot1, delta_trans, delta_rot2]
        """
        # Unpack control inputs
        delta_rot1, delta_trans, delta_rot2 = u_t
        
        # Unpack robot pose
        x, y, yaw = self.state[0:3]
        
        # Predict new robot pose
        new_x = x + delta_trans * math.cos(yaw + delta_rot1)
        new_y = y + delta_trans * math.sin(yaw + delta_rot1)
        new_yaw = yaw + delta_rot1 + delta_rot2
        
        # Normalize the yaw angle to be within [-pi, pi]
        new_yaw = (new_yaw + math.pi) % (2 * math.pi) - math.pi
        
        # Update state vector
        self.state[0] = new_x
        self.state[1] = new_y
        self.state[2] = new_yaw
        
        # Jacobian of the motion model w.r.t the state (F_x)
        # F_x is a 3xN matrix where N is state dimension
        F_x = np.eye(self.state_dim)
        F_x[0, 2] = -delta_trans * math.sin(yaw + delta_rot1)
        F_x[1, 2] = delta_trans * math.cos(yaw + delta_rot1)

        # Jacobian of the motion model w.r.t the control input (F_u)
        # F_u is a 3x3 matrix
        F_u = np.zeros((3, 3))
        F_u[0, 0] = -delta_trans * math.sin(yaw + delta_rot1)
        F_u[0, 1] = math.cos(yaw + delta_rot1)
        F_u[1, 0] = delta_trans * math.cos(yaw + delta_rot1)
        F_u[1, 1] = math.sin(yaw + delta_rot1)
        F_u[2, 0] = 1.0
        F_u[2, 2] = 1.0
        
        # Predict new covariance
        # P = F_x * P * F_x.T + F_u * Q * F_u.T
        motion_noise_covariance = F_u @ self.Q @ F_u.T
        self.covariance[0:3, 0:3] += motion_noise_covariance
        
        self.covariance = F_x @ self.covariance @ F_x.T

    def update(self, measurements, laser_scan_msg):
        """
        EKF Update step with new measurements.
        measurements: list of observed landmark features [range, bearing, landmark_id]
        laser_scan_msg: ROS LaserScan message for feature extraction (optional)
        """
        
        # Data Association and Update for each measurement
        for obs_range, obs_angle_rel_robot, landmark_id in measurements:
            
            # --- Data Association ---
            if landmark_id not in self.landmarks:
                # This is a new landmark, so initialize it
                self.logger.info(f"Initializing new landmark with ID: {self.next_landmark_id}")
                
                # Expand state and covariance matrix
                current_state_dim = self.state.shape[0]
                new_state_dim = current_state_dim + 2
                
                new_state = np.zeros(new_state_dim)
                new_state[:current_state_dim] = self.state
                
                new_covariance = np.zeros((new_state_dim, new_state_dim))
                new_covariance[:current_state_dim, :current_state_dim] = self.covariance
                
                # Initialize the new landmark position in the state
                robot_x, robot_y, robot_yaw = self.state[0:3]
                landmark_x = robot_x + obs_range * math.cos(robot_yaw + obs_angle_rel_robot)
                landmark_y = robot_y + obs_range * math.sin(robot_yaw + obs_angle_rel_robot)
                new_state[-2] = landmark_x
                new_state[-1] = landmark_y
                
                # Initialize landmark covariance
                # Calculate Jacobian for landmark initialization
                # J_g = [d_landmark_pos/d_robot_pose, d_landmark_pos/d_measurement]
                J_g = np.zeros((2, current_state_dim + 2))
                J_g[0, 0] = 1.0
                J_g[1, 1] = 1.0
                J_g[:, 2] = [-obs_range * math.sin(robot_yaw + obs_angle_rel_robot), obs_range * math.cos(robot_yaw + obs_angle_rel_robot)]
                
                # Initialize new landmark covariance based on robot pose and measurement uncertainty
                # P_new = J_g * P_current * J_g.T + G_z * R * G_z.T
                
                # A more common initialization is to simply add a large covariance
                # This ensures the EKF can quickly converge to the true position
                new_covariance[current_state_dim:, current_state_dim:] = np.diag([0.5, 0.5])
                
                self.state = new_state
                self.covariance = new_covariance
                self.state_dim = new_state_dim
                self.landmarks[self.next_landmark_id] = self.state_dim - 2
                self.next_landmark_id += 1
                
                continue # No update for new landmarks in this step

            # --- Update for known landmarks ---
            
            # Find the landmark's position in the state vector
            landmark_idx = self.landmarks[landmark_id]
            landmark_x = self.state[landmark_idx]
            landmark_y = self.state[landmark_idx+1]
            
            # Unpack robot pose
            robot_x, robot_y, robot_yaw = self.state[0:3]
            
            # Calculate expected measurement from current state prediction
            dx = landmark_x - robot_x
            dy = landmark_y - robot_y
            
            expected_range = math.sqrt(dx**2 + dy**2)
            expected_bearing = math.atan2(dy, dx) - robot_yaw
            
            # Normalize bearing to [-pi, pi]
            expected_bearing = (expected_bearing + math.pi) % (2 * math.pi) - math.pi
            
            # Measurement residual (innovation)
            y_t = np.array([obs_range - expected_range, obs_angle_rel_robot - expected_bearing])
            
            # Normalize bearing residual
            y_t[1] = (y_t[1] + math.pi) % (2 * math.pi) - math.pi
            
            # Jacobian of the measurement model w.r.t the state (H)
            H = np.zeros((2, self.state_dim))
            H[0, 0] = -dx / expected_range
            H[0, 1] = -dy / expected_range
            H[1, 0] = dy / expected_range**2
            H[1, 1] = -dx / expected_range**2
            
            H[0, 2] = 0.0
            H[1, 2] = -1.0
            
            H[0, landmark_idx] = dx / expected_range
            H[0, landmark_idx+1] = dy / expected_range
            H[1, landmark_idx] = -dy / expected_range**2
            H[1, landmark_idx+1] = dx / expected_range**2
            
            # Innovation Covariance (S)
            S = H @ self.covariance @ H.T + self.R
            
            # Kalman Gain (K)
            K = self.covariance @ H.T @ np.linalg.inv(S)
            
            # Update state and covariance
            self.state = self.state + K @ y_t
            self.covariance = (np.eye(self.state_dim) - K @ H) @ self.covariance
    
    def get_robot_pose(self):
        """Returns the current estimated robot pose [x, y, yaw]."""
        return self.state[0:3]
        
    def get_landmarks(self):
        """Returns a list of landmark positions [x, y] with their IDs."""
        landmarks_list = []
        for landmark_id, idx in self.landmarks.items():
            landmarks_list.append({
                'id': landmark_id,
                'x': self.state[idx],
                'y': self.state[idx+1]
            })
        return landmarks_list
        

class FeatureBasedSLAMLNode(Node):
    def __init__(self):
        super().__init__('feature_based_slam_node')
        self.get_logger().info('EKF Feature-based SLAM Node has been started.')

        # --- Parameters ---
        self.map_frame = self.declare_parameter('map_frame', 'map').value
        self.odom_frame = self.declare_parameter('odom_frame', 'odom').value
        self.base_frame = self.declare_parameter('base_frame', 'base_link').value
        self.laser_frame = self.declare_parameter('laser_frame', 'laser_frame').value
        self.feature_distance_threshold = self.declare_parameter('feature_distance_threshold', 1.5).value
        self.mah_dist_threshold = self.declare_parameter('mah_dist_threshold', 2.0).value

        # --- State variables ---
        initial_pose = np.array([0.0, 0.0, 0.0])
        # Pass the node's logger to the EKF_SLAM class
        self.slam = EKF_SLAM(state_dim=3, initial_pose=initial_pose, logger=self.get_logger())
        self.last_odom_pose = None
        self.tf_buffer = Buffer()
        self.tf_listener = TransformListener(self.tf_buffer, self)
        
        # --- ROS 2 Publishers and Subscribers ---
        self.odom_sub = self.create_subscription(Odometry, '/odom', self.odom_callback, 10)
        self.laser_sub = self.create_subscription(LaserScan, '/scan', self.laser_callback, 10)
        
        self.pose_pub = self.create_publisher(PoseStamped, '/slam_pose', 10)
        self.landmark_pub = self.create_publisher(MarkerArray, '/landmarks', 10)
        self.tf_broadcaster = TransformBroadcaster(self)

    def quaternion_to_yaw(self, q):
        # Using tf_transformations for a more robust conversion
        euler = tf_transformations.euler_from_quaternion([q.x, q.y, q.z, q.w])
        return euler[2]
    
    def yaw_to_quaternion(self, yaw):
        from geometry_msgs.msg import Quaternion
        q_ros = Quaternion()
        q = tf_transformations.quaternion_from_euler(0, 0, yaw)
        q_ros.x = q[0]
        q_ros.y = q[1]
        q_ros.z = q[2]
        q_ros.w = q[3]
        return q_ros

    def extract_features_from_scan(self, laser_scan_msg):
        """
        A very simple feature extraction method: detect distinct objects.
        This simplified version finds points with a large distance change.
        Returns a list of [range, bearing, landmark_id].
        """
        features = []
        
        # Create a list of ranges and their corresponding angles
        ranges = laser_scan_msg.ranges
        angles = [laser_scan_msg.angle_min + i * laser_scan_msg.angle_increment for i in range(len(ranges))]
        
        for i in range(1, len(ranges)):
            current_range = ranges[i]
            prev_range = ranges[i-1]
            
            # Check for large jump in distance, indicating an object edge
            if not (np.isinf(current_range) or np.isinf(prev_range)):
                if abs(current_range - prev_range) > self.feature_distance_threshold:
                    # Treat the point just before the jump as a feature
                    features.append((prev_range, angles[i-1], self.slam.next_landmark_id))
        
        # Add a feature for the last point if it's valid
        last_range = ranges[-1]
        if not np.isinf(last_range):
            features.append((last_range, angles[-1], self.slam.next_landmark_id))

        return features

    def odom_callback(self, msg):
        """
        Handles the odometry message to perform the prediction step.
        """
        if self.last_odom_pose is None:
            self.last_odom_pose = msg.pose.pose
            return

        current_pose = msg.pose.pose
        last_pose = self.last_odom_pose
        self.last_odom_pose = current_pose

        current_yaw = self.quaternion_to_yaw(current_pose.orientation)
        last_yaw = self.quaternion_to_yaw(last_pose.orientation)

        delta_rot1 = math.atan2(current_pose.position.y - last_pose.position.y,
                                current_pose.position.x - last_pose.position.x) - last_yaw
        delta_trans = math.sqrt((current_pose.position.x - last_pose.position.x)**2 +
                                (current_pose.position.y - last_pose.position.y)**2)
        delta_rot2 = current_yaw - last_yaw - delta_rot1
        
        u_t = np.array([delta_rot1, delta_trans, delta_rot2])
        self.slam.predict(u_t)
        self.publish_state()


    def laser_callback(self, msg):
        """
        Handles the laser scan message to perform the update step.
        """
        if self.last_odom_pose is None:
            return
            
        self.get_logger().info('Received laser scan. Updating state with features.')
        
        # Extract features from the laser scan
        features = self.extract_features_from_scan(msg)
        
        if features:
            self.slam.update(features, msg)
            self.publish_state()
            self.publish_landmarks()
        else:
            self.get_logger().info('No features detected in this scan.')
    
    def publish_state(self):
        """
        Publishes the robot's estimated pose and TF.
        """
        robot_pose = self.slam.get_robot_pose()
        
        # Publish pose
        pose_msg = PoseStamped()
        pose_msg.header.stamp = self.get_clock().now().to_msg()
        pose_msg.header.frame_id = self.map_frame
        pose_msg.pose.position.x = robot_pose[0]
        pose_msg.pose.position.y = robot_pose[1]
        pose_msg.pose.orientation = self.yaw_to_quaternion(robot_pose[2])
        self.pose_pub.publish(pose_msg)

        # Publish map -> base_link transform for visualization
        t = TransformStamped()
        t.header.stamp = self.get_clock().now().to_msg()
        t.header.frame_id = self.map_frame
        t.child_frame_id = self.base_frame
        t.transform.translation.x = robot_pose[0]
        t.transform.translation.y = robot_pose[1]
        t.transform.rotation = self.yaw_to_quaternion(robot_pose[2])
        self.tf_broadcaster.sendTransform(t)

    def publish_landmarks(self):
        """
        Publishes the visualized landmarks.
        """
        landmarks = self.slam.get_landmarks()
        marker_array_msg = MarkerArray()

        for landmark in landmarks:
            marker = Marker()
            marker.header.frame_id = self.map_frame
            marker.header.stamp = self.get_clock().now().to_msg()
            marker.ns = "landmarks"
            marker.id = landmark['id']
            marker.type = Marker.SPHERE
            marker.action = Marker.ADD
            marker.pose.position.x = landmark['x']
            marker.pose.position.y = landmark['y']
            marker.pose.position.z = 0.0
            marker.scale.x = 0.2
            marker.scale.y = 0.2
            marker.scale.z = 0.2
            marker.color.a = 1.0
            marker.color.r = 0.0
            marker.color.g = 1.0
            marker.color.b = 0.0
            marker_array_msg.markers.append(marker)
        
        self.landmark_pub.publish(marker_array_msg)
        

def main(args=None):
    rclpy.init(args=args)
    slam_node = FeatureBasedSLAMLNode()
    try:
        rclpy.spin(slam_node)
    except KeyboardInterrupt:
        pass
    finally:
        slam_node.destroy_node()
        rclpy.shutdown()

if __name__ == '__main__':
    main()

